-- 外研社(fltrp)必修一 情景闯关题(context_questions, grade=12, volume='elective4', publisher='fltrp')。Aaron 跑。幂等(只删 fltrp 本册)。
BEGIN;
DELETE FROM public.context_questions WHERE publisher='fltrp' AND volume='elective4';

COMMIT;
SELECT unit, count(*) FROM public.context_questions WHERE publisher='fltrp' AND volume='elective4' GROUP BY unit ORDER BY unit;
